 848					"kind=public-followup and typed public_followup data must be present together",
 849				);
 850			}
 851			if (hasFollowup) {
 852				if (meta.hold) {
 853					validation("Public-followup obligations cannot use dispatch holds");
 854				}
 855				task.public_followup = decodePublicFollowup(followup);
 856				assertPublicFollowupTaskState(task.state, task.public_followup, id);
 857				assertPublicFollowupTaskContent(task, task.public_followup);
 858			}
 859			const extra = {
 860				...(meta.meta ?? {}),
 861				ado_id: item.id,
 862				ado_area: str(fields[F_AREA]),
 863			};
 864			task.meta = extra;
 865			return task;
 866		}
 867	
 868		private depsOf(item: WorkItem, slugs: Map<number, string>): Dep[] {
 869			const deps: Dep[] = [];
 870			const ownerId = slugs.get(item.id)!;
 871			for (const relation of item.relations ?? []) {
 872				const target = relationTargetId(relation.url);
 873				const slug = target === undefined ? undefined : slugs.get(target);
 874				if (!slug) continue;
 875				const text = comment(relation);
 876				if (relation.rel === REL_BLOCKED_BY) {
 877					deps.push(dep("blocked-by", slug, text));
 878				} else {
 879					const parent = parentReason(relation, ownerId);
 880					if (parent !== undefined) {
 881						deps.push(dep("parent", slug, parent));
 882						continue;
 883					}
 884					const discovered = discoveredReason(relation, ownerId);
 885					if (discovered !== undefined) {
 886						deps.push(dep("discovered-from", slug, discovered));
 887					}
 888				}
 889			}
 890			return deps;
 891		}
 892	
 893		async get(id: string): Promise<Task | null> {
 894			const item = await this.loadItem(id);
 895			if (!item) return null;
 896			return this.toTask(item, await this.slugMap([item]));
 897		}
 898	
 899		async list(query: TaskQuery): Promise<{ items: Task[]; total: number }> {
 900			const ids = await this.client.queryIds(this.wiql([]));
 901			const workItems = await this.client.getMany(ids);
 902			for (const item of workItems) this.requireInScope(item);
 903			const slugs = await this.slugMap(workItems);
 904			let items = workItems.map((item) => this.toTask(item, slugs));
 905			if (query.state) items = items.filter((t) => t.state === query.state);
 906			if (query.repo) items = items.filter((t) => t.repo === query.repo);
 907			if (query.kind) items = items.filter((t) => t.kind === query.kind);
 908			const total = items.length;
 909			if (query.limit !== undefined && query.limit >= 0) {
 910				items = items.slice(0, query.limit);
 911			}
 912			return { items, total };
 913		}
 914	
 915		// ---------------------------------------------------------------------
 916		// Write helpers
 917		// ---------------------------------------------------------------------
 918	
 919		private metaBlob(task: Task, pendingClosed?: string): string {
 920			const blob: MetaBlob = { v: META_VERSION };
 921			if (task.priority !== undefined) blob.priority = task.priority;
 922			if (task.hold) blob.hold = task.hold;
 923			const links = normalizeTypedLinks(task.links);
 924			if (links.length > 0) blob.links = links;
 925			if (task.created) blob.created = task.created;
 926			if (pendingClosed) blob.pending_closed = pendingClosed;
 927			else if (task.closed) blob.closed = task.closed;
 928			const meta = { ...task.meta };
 929			delete meta.ado_id;
 930			delete meta.ado_area;
 931			if (Object.keys(meta).length > 0) blob.meta = meta;
 932			return JSON.stringify(blob);
 933		}
 934	
 935		/** Rebuild the tag string, preserving tags this backend does not own. */
 936		private tagString(item: WorkItem | undefined, task: Task): string {
 937			const foreign = parseTags(item?.fields[F_TAGS]).filter(
 938				(tag) => !tag.startsWith("kind:") && !tag.startsWith("repo:"),
 939			);
 940			const owned = [
 941				...(task.kind ? [`kind:${task.kind}`] : []),
 942				...(task.repo ? [`repo:${task.repo}`] : []),
 943			];
 944			return [...owned, ...foreign].join("; ");
 945		}
 946	
 947		private async applyPatch(
 948			item: WorkItem,
 949			ops: JsonPatchOp[],
 950			expectedArea?: string,
 951		): Promise<WorkItem> {
 952			if (item.rev === undefined) {
 953				throw new AxiError(
 954					`Work item ${item.id} has no revision; refusing an unguarded update`,
 955					"CONFLICT",
 956				);
 957			}
 958			const expectedId = this.taskId(item);
 959			if (!expectedId) {
 960				validation(`Work item ${item.id} has no ${this.idField} value`);
 961			}
 962			let responseReturned = false;
 963			try {
 964				const updated = await this.client.update(item.id, [
 965					{ op: "test", path: "/rev", value: item.rev },
 966					...ops,
 967				]);
 968				responseReturned = true;
 969				this.requireMutationResult(updated, expectedId, expectedArea);
 970				requirePatchPostconditions(item, updated, ops);
1760				task.state = "done";
1761				task.closed = this.now();
1762				assertPublicFollowupTaskState(task.state, next, id);
1763				ops.push(add(`/fields/${F_STATE}`, this.adoState("done")));
1764			} else {
1765				assertPublicFollowupTaskState(task.state, next, id);
1766			}
1767			ops.push(add(`/fields/${this.metaField}`, this.metaBlob(task)));
1768			const updated = await this.applyPatch(item, ops);
1769			return this.toTask(updated, slugs);
1770		}
1771	}
1772	
1773	function add(path: string, value: unknown): JsonPatchOp {
1774		return { op: "add", path, value };
1775	}
1776	
1777	function dep(type: Dep["type"], id: string, reason: string): Dep {
1778		return reason.trim() === ""
1779			? { type, id }
1780			: { type, id, reason: reason.trim() };
1781	}
1782	
1783	function tagValue(tags: string[], prefix: string): string | undefined {
1784		const matches = tags.filter((tag) => tag.startsWith(`${prefix}:`));
1785		if (matches.length > 1) {
1786			validation(`Azure DevOps work item has multiple ${prefix}: tags`);
1787		}
1788		const match = matches[0];
1789		return match ? match.slice(prefix.length + 1).trim() || undefined : undefined;
1790	}
1791	
1792	function bodyHasLine(body: string | undefined, line: string): boolean {
1793		return (body ?? "").split("\n").some((entry) => entry.trim() === line.trim());
1794	}
1795	
1796	/** Escape a WIQL single-quoted literal. */
1797	function sq(value: string): string {
1798		return value.replace(/'/g, "''");
1799	}

