 947		private async applyPatch(
 948			item: WorkItem,
 949			ops: JsonPatchOp[],
 950			expectedArea?: string,
 951		): Promise<WorkItem> {
 952			if (item.rev === undefined) {
 953				throw new AxiError(
 954					`Work item ${item.id} has no revision; refusing an unguarded update`,
 955					"CONFLICT",
 956				);
 957			}
 958			const expectedId = this.taskId(item);
 959			if (!expectedId) {
 960				validation(`Work item ${item.id} has no ${this.idField} value`);
 961			}
 962			let responseReturned = false;
 963			try {
 964				const updated = await this.client.update(item.id, [
 965					{ op: "test", path: "/rev", value: item.rev },
 966					...ops,
 967				]);
 968				responseReturned = true;
 969				this.requireMutationResult(updated, expectedId, expectedArea);
 970				requirePatchPostconditions(item, updated, ops);
 971				return updated;
 972			} catch (error) {
 973				if (!responseReturned && isDefinitiveAdoRejection(error)) throw error;
 974				const reason = error instanceof Error ? `: ${error.message}` : "";
 975				throw new AxiError(
 976					`Work item ${item.id} update has an unconfirmed outcome${reason}`,
 977					"CONFLICT",
 978					[`Inspect task "${expectedId}" in Azure DevOps before retrying`],
 979				);
 980			}
 981		}
