 983		private async rollbackRelations(
 984			item: WorkItem,
 985			relations: NonNullable<WorkItem["relations"]>,
 986		): Promise<void> {
 987			if (item.rev === undefined) {
 988				throw new AxiError(
 989					`Work item ${item.id} has no revision; refusing an unguarded update`,
 990					"CONFLICT",
 991				);
 992			}
 993			const available = (item.relations ?? []).map((relation, index) => ({
 994				index,
 995				key: normalizedRelations([relation])[0],
 996			}));
 997			const used = new Set<number>();
 998			const indexes = relations.map((relation) => {
 999				const key = normalizedRelations([relation])[0];
1000				const match = available.find(
1001					(candidate) => candidate.key === key && !used.has(candidate.index),
1002				);
1003				if (!match) {
1004					throw new AxiError(
1005						`Work item ${item.id} did not return an appended relation`,
1006						"CONFLICT",
1007					);
1008				}
1009				used.add(match.index);
1010				return match.index;
1011			});
1012			const ops: JsonPatchOp[] = indexes
1013				.sort((left, right) => right - left)
1014				.map((index) => ({ op: "remove", path: `/relations/${index}` }));
1015			const rolledBack = await this.client.update(item.id, [
1016				{ op: "test", path: "/rev", value: item.rev },
1017				...ops,
1018			]);
1019			if (rolledBack.id !== item.id) {
1020				throw new AxiError(
1021					`Azure DevOps returned work item ${rolledBack.id}, expected ${item.id}`,
1022					"CONFLICT",
1023				);
1024			}
1025			requirePatchPostconditions(item, rolledBack, ops);
1026		}
