1665			const ownerId = slugs.get(item.id)!;
1666			const indices = relations.flatMap((relation, index) => {
1667				const target = relationTargetId(relation.url);
1668				const targetId = target === undefined ? undefined : slugs.get(target);
1669				if (targetId !== depId) {
1670					if (targetId?.toLowerCase() === depId.toLowerCase()) {
1671						throw new AxiError(
1672							`Task "${depId}" changed identity while it was being loaded`,
1673							"CONFLICT",
1674							["Retry the command after checking the Azure DevOps join field"],
1675						);
1676					}
1677					return [];
1678				}
1679				const matches =
1680					dep.type === "blocked-by"
1681						? relation.rel === REL_BLOCKED_BY
1682						: dep.type === "parent"
1683							? parentReason(relation, ownerId) !== undefined
1684							: discoveredReason(relation, ownerId) !== undefined;
1685				return matches ? [index] : [];
1686			});
1687			if (indices.length === 0) return false;
1688			await this.applyPatch(
1689				item,
1690				indices
