1697		async updatePublicFollowup(
1698			id: string,
1699			mutation: PublicFollowupMutation,
1700		): Promise<Task> {
1701			const item = await this.requireItem(id);
1702			const slugs = await this.slugMap([item]);
1703			const task = this.toTask(item, slugs);
1704			if (!isPublicFollowupTask(task) || !task.public_followup) {
1705				validation(`Task "${id}" is not a public-followup obligation`);
1706			}
1707			const expected = normalizePublicFollowup(mutation.expectedPublicFollowup);
1708			if (
1709				task.public_followup.revision !== mutation.expectedRevision ||
1710				expected.revision !== mutation.expectedRevision ||
1711				!canonicalEqual(task.public_followup, expected)
1712			) {
1713				throw new AxiError(
1714					`Public-followup "${id}" changed; retry the command`,
1715					"CONFLICT",
1716					["Read the latest obligation revision, then retry"],
1717				);
1718			}
1719			if (task.state === "done") {
1720				throw new AxiError(
1721					`Public-followup "${id}" is already complete`,
1722					"CONFLICT",
1723				);
1724			}
1725			if (mutation.requireUnblocked) {
1726				// ponytail: blocker state is read, then only the obligation revision is tested.
1727				// Serialize graph-sensitive ADO writes if blocker reopen races matter in practice.
1728				const { items } = await this.list({});
1729				const byId = new Map(items.map((entry) => [entry.id, entry]));
1730				const blocked = task.deps.some((d) => {
1731					if (d.type !== "blocked-by") return false;
1732					const blocker = byId.get(d.id);
1733					return blocker !== undefined && blocker.state !== "done";
1734				});
1735				if (blocked) {
1736					validation(
1737						"Cannot begin delivery while the obligation has an active blocker",
1738					);
1739				}
1740			}
1741	
1742			const next = normalizePublicFollowup(mutation.publicFollowup);
1743			assertPublicFollowupMutation(task.public_followup, next);
1744			if (mutation.complete && !isPublicFollowupTerminal(next)) {
1745				validation(
1746					"Only a posted receipt or Captain-approved waiver may complete a public-followup",
1747				);
1748			}
1749			if (!mutation.complete && isPublicFollowupTerminal(next)) {
1750				validation(
1751					"Terminal public-followup data requires an atomic completion mutation",
1752				);
1753			}
1754	
1755			task.public_followup = next;
1756			const ops: JsonPatchOp[] = [
1757				add(`/fields/${this.followupField}`, encodePublicFollowup(next)),
1758			];
1759			if (mutation.complete) {
1760				task.state = "done";
1761				task.closed = this.now();
1762				assertPublicFollowupTaskState(task.state, next, id);
1763				ops.push(add(`/fields/${F_STATE}`, this.adoState("done")));
1764			} else {
1765				assertPublicFollowupTaskState(task.state, next, id);
1766			}
1767			ops.push(add(`/fields/${this.metaField}`, this.metaBlob(task)));
1768			const updated = await this.applyPatch(item, ops);
1769			return this.toTask(updated, slugs);
1770		}
1771	}
